import{_ as t,l as s,o as a,c,v as o,p as n,x as d,d as r,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"设备节点","description":"","frontmatter":{"title":"设备节点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/device-nodes.md","filePath":"cs/device-nodes.md","lastUpdated":1789023840000}'),h={name:"cs/device-nodes.md"};function m(_,e,f,u,E,v){const i=s("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="设备节点" tabindex="-1">设备节点 <a class="header-anchor" href="#设备节点" aria-label="Permalink to &quot;设备节点&quot;">​</a></h1><div class="epigraph"><p>设备节点是带主次设备号的 inode：打开它不读数据块，而是把后续 I/O 送到对应驱动。</p><footer>—— 据 Thompson, UNIX Implementation；Bach；Linux devices.txt 对主次号的整理</footer></div><p><a href="/cs/tmpfs">上一课</a>的文件仍是页。Unix「一切皆文件」还包括磁盘、终端、随机数：<a href="/cs/inode-dir">inode</a> 类型为字符或块设备，内容是 <strong>dev_t</strong>。缺口是设备节点与 <a href="/cs/vfs">VFS</a> 如何接到驱动，而不是存储栈的调度器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若用户必须 <code>ioctl</code> 一个隐藏句柄才能访问磁盘，POSIX 工具链裂开。设备节点：<code>mknod</code> 在某文件系统（常为 devtmpfs）上造 inode，<code>open</code> 走 <code>chrdev_open</code>/<code>blkdev_open</code>，fops 来自驱动。块设备还可再被挂载成 FS——同一盘既有 <code>/dev/sda</code> 又有 <code>/</code>。缺口：主次号分配、<code>uevent</code> 与后课 udev、以及权限（谁能打开裸盘）。</p><p><span class="marginnote">字符设备按字节流；块设备按块，可走页缓存（缓冲 I/O）。裸盘 <code>O_DIRECT</code> 是后课。本课不把 NVMe 多队列写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>read(/dev/zero)</code>：驱动填零，不经块分配器。<code>read(/dev/sda)</code>：块层按偏移读扇区，可进页缓存（bdev inode）。<code>ioctl</code> 传送设备特定命令。对照普通文件：没有 extent，偏移是设备地址。对照 <a href="/cs/fuse">FUSE</a>：用户态也可以实现字符设备，但经典路径是内核 cdev。</p>',8)),(a(),n(p,null,{default:d(()=>[l(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PATH%5B%22%2Fdev%2Fsda%22%5D%20--%3E%20INO%5B%22%E8%AE%BE%E5%A4%87%20inode%22%5D%0A%20%20INO%20--%3E%20MAJ%5B%22%E4%B8%BB%E6%AC%A1%E8%AE%BE%E5%A4%87%E5%8F%B7%22%5D%0A%20%20MAJ%20--%3E%20DRV%5B%22%E9%A9%B1%E5%8A%A8%20fops%22%5D%0A%20%20DRV%20--%3E%20BLK%5B%22%E5%9D%97%E5%B1%82%E6%88%96%E5%AD%97%E7%AC%A6%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>设备节点把驱动登记进文件系统名空间，使权限、打开计数、poll 与普通文件共用 VFS。这是 Unix 的关键接头：备份、dd、加密卷都从打开一个节点开始。不要把本课写成硬件总线枚举全文——<a href="/cs/device-model-binding">设备模型</a> 在启动课序。</p><p>与 <a href="/cs/rename-atomicity">rename</a>：设备节点可改名，主次号不变；删除节点不卸载驱动。</p><p>实现上：devtmpfs 在内核里造节点，udev 再改名。容器里 mknod 常被 cap 与设备 cgroup 拦住，不是 VFS 不懂设备。块设备的 bdev inode 有自己的页缓存，和文件系统页缓存是两套。 读法上只引用<a href="/cs/tmpfs">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>设备节点</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 namespace 里的设备可见性全部规则。不保证容器里 mknod 被 cap 拦住的每条路径——capabilities 后课。下一课从「打开了文件/设备」走到读路径优化：预读。</p><p>版本字段会变，课序钉的是机制对象「设备节点」，不是某一主线内核的结构体名。 后课默认：设备是带主次号的 inode。顺序读如何提前拉块进页缓存，下一课预读。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设备节点把主次号接到驱动 fops。</li><li>块设备可再被挂载；字符设备是字节接口。</li><li>预读是下一课。</li><li>出处：Thompson；Bach；Linux device 文档；Tanenbaum <em>MOS</em>。</li></ul>',11))])}const T=t(h,[["render",m]]);export{B as __pageData,T as default};
